 p.at('body');p.poly([(22,25),(29,22),(37,24),(43,29),(43,36),(38,44),(31,48),(22,45),(16,39),(15,31),(18,28)],'t','o');p.poly([(22,27),(28,24),(34,25),(38,29),(36,33),(29,35),(20,33),(18,30)],'T');p.poly([(24,27),(27,26),(31,27),(30,30),(24,31)],'y');p.line([(25,27),(28,27)],'Y');p.poly([(23,36),(30,35),(37,36),(39,39),(34,45),(28,46),(21,42)],'T');p.line([(24,40),(27,41),(30,40),(32,43)],'b');p.line([(19,32),(18,36),(21,39)],'b');p.line([(30,26),(32,30),(31,32)],'t')
